SELECT orders.*, Trim$([fname])+"  "+Trim$([pname]) & " " & IIf(nz([cust_list]![sel])<>"",[cust_list]![sel],nz([cust_list]![tel])) AS namew, Trim$([pname])+"  "+Trim$([fname]) AS prname, [cust_list]![sel] AS qtel, Trim$([pname]) AS prati, cust_list.moadon, orders.al2 AS q, orders.odate AS f1, orders.mwdate AS f2, orders.CDate AS f3, xg_GetSubString(nz(IIf(nz([mwdate])<>"",nz(DLookUp("[checkname]","checks","[numw] = " & [orders]![numw] & " and [chdate]=" & "#" & NZ([mwdate]) & "#")),nz(DLookUp("[checkname]","checks","[numw] = " & [orders]![numw] & " and [chdate]=" & "#" & NZ([odate]) & "#")))),1," ") AS f4, cust_list.pname AS f5p, cust_list.fname AS f5f, nz([FirstName]) AS f6, orders.rdate AS f7, IIf(nz([orders]![cdate])<>"",DateAdd("d",90,[orders]![cdate]),Null) AS f8, IIf(nz([orders]![cdate])<>"",DateAdd("d",14,[orders]![cdate]),Null) AS f9, Val(nz([cadsh])) AS f10, Val(nz([cmsgr])) AS f11, "15-1-" & nz([cust_list]![number]) AS f12
FROM cust_list INNER JOIN ((tb_qnum INNER JOIN orders ON tb_qnum.qnum=orders.ordernum) LEFT JOIN employees ON orders.EmployeeID=employees.EmployeeID) ON cust_list.numw=orders.numw
WHERE (((orders.al2)=False));

SELECT orders.*, Trim$([fname])+"  "+Trim$([pname]) & " " & IIf(nz([cust_list]![sel])<>"",[cust_list]![sel],nz([cust_list]![tel])) AS namew, Trim$([pname])+"  "+Trim$([fname]) AS prname, [cust_list]![sel] AS qtel, Trim$([pname]) AS prati, cust_list.moadon, orders.al2 AS q, orders.odate AS f1, orders.mwdate AS f2, orders.CDate AS f3, xg_GetSubString(nz(IIf(nz([mwdate])<>"",nz(DLookUp("[checkname]","checks","[numw] = " & [orders]![numw] & " and [chdate]=" & "#" & NZ([mwdate]) & "#")),nz(DLookUp("[checkname]","checks","[numw] = " & [orders]![numw] & " and [chdate]=" & "#" & NZ([odate]) & "#")))),1," ") AS f4, cust_list.fname AS f5f, nz([FirstName]) AS f6, orders.rdate AS f7, IIf(nz([orders]![cdate])<>"",DateAdd("d",90,[orders]![cdate]),Null) AS f8, IIf(nz([orders]![cdate])<>"",DateAdd("d",14,[orders]![cdate]),Null) AS f9, Val(nz([cadsh])) AS f10, Val(nz([cmsgr])) AS f11, "15-1-" & nz([cust_list]![number]) AS f12
FROM cust_list INNER JOIN ((tb_qnum INNER JOIN orders ON tb_qnum.qnum=orders.ordernum) LEFT JOIN employees ON orders.EmployeeID=employees.EmployeeID) ON cust_list.numw=orders.numw
WHERE (((orders.al2)=True));

SELECT orders.odate, orders.mwdate, orders.ordernum, orders.cn, orders.numw, orders.gf_price, orders.gpay,  orders.gdate, orders.rdate, orders.CDate,  orders.multia, orders.multib, orders.catga,  orders.totala,  orders.lang , orders.qmsgr,orders.yeda, orders.swtk, orders.color, orders.pgpricet, orders.pdisct, orders.gpricet, orders.al2, orders.ar2, orders.qpart, orders.ob_comp, orders.ob_type, orders.ob_size, orders.ocolor, orders.bar_size, tb_ad_catalog.hevra AS ocomp, tb_ad_catalog.typ AS og_type, tb_ad_catalog.sapak AS sapaka, orders.sapakm, orders.sun, orders.pbprice, orders.pdisc, orders.bprice,orders.wnuma AS adw
